<script setup lang="ts">
import { reactive, ref } from 'vue'
import { createPropertyLead } from '../../api/properties'
const form = reactive({ sourceName:'', sourcePhone:'', community:'', location:'', layout:'', expectedRentMonthly:0, note:'' })
const mediaCount = ref(0)
const chooseMedia = () => uni.chooseImage({ count: 9, success: (res) => { mediaCount.value += res.tempFilePaths.length } })
const submit = async () => { if (!form.community || !form.sourcePhone) return uni.showToast({ title:'请填写小区和联系电话', icon:'none' }); await createPropertyLead(form); uni.showToast({ title:'线索已提交' }); setTimeout(() => uni.navigateBack(), 500) }
</script>
<template><view class="page"><view class="tip card"><view class="title small">提供房源线索</view><view class="muted">提交基础信息后，小皮会联系你并实地核实。正式房源由小皮拍摄和发布。</view></view><view class="card"><view class="field"><text>联系人</text><input v-model="form.sourceName" placeholder="怎么称呼你" /></view><view class="field"><text>联系电话</text><input v-model="form.sourcePhone" type="number" placeholder="方便小皮联系" /></view><view class="field"><text>小区</text><input v-model="form.community" placeholder="请输入小区名称" /></view><view class="field"><text>位置</text><input v-model="form.location" placeholder="区域 / 地铁 / 商圈" /></view><view class="field"><text>户型</text><input v-model="form.layout" placeholder="例如：一室一厅" /></view><view class="field"><text>预期租金</text><input v-model.number="form.expectedRentMonthly" type="number" placeholder="请输入租金" /></view><view class="field column"><text>补充说明</text><textarea v-model="form.note" placeholder="入住时间、房屋情况等"></textarea></view><view class="media" @click="chooseMedia">＋ 添加参考图片 <text v-if="mediaCount">已选 {{ mediaCount }} 张</text></view></view><view class="button" @click="submit">提交房源线索</view></view></template>
<style scoped>.field{display:flex;align-items:center;padding:24rpx 0;border-bottom:1rpx solid #edf4f1}.field text{width:150rpx;color:#57857e}.field input{flex:1}.column{display:block}.column textarea{width:100%;height:150rpx;margin-top:18rpx}.media{margin-top:24rpx;padding:40rpx;text-align:center;border:2rpx dashed #a8d9cf;border-radius:20rpx;color:#0f8177}.media text{display:block;margin-top:12rpx;color:#78a39d}</style>
